using namespace std;

class Solution {
public:
    vector<int> bestReachableTower(vector<vector<int>>& towers, vector<int>& center, int radius) {
        int cx = center[0], cy = center[1];
        int r2 = radius * radius;
        int best_score = -1;
        vector<int> best_tower = {};
        for (const auto& t : towers) {
            int x = t[0], y = t[1], q = t[2];
            int d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
            if (d2 <= r2) {
                double d = sqrt(d2);
                int score = floor(q / (1.0 + d));
                if (score > best_score) {
                    best_score = score;
                    best_tower = {x, y};
                } else if (score == best_score && !best_tower.empty()) {
                    if (vector<int>{x, y} < best_tower) best_tower = {x, y};
                }
            }
        }
        return best_tower;
    }
