import java.util.*;

class Solution {
    public int[] bestReachableTower(int[][] towers, int[] center, int radius) {
        int cx = center[0], cy = center[1];
        int r2 = radius * radius;
        int bestScore = -1;
        int[] bestTower = new int[0];
        for (int[] t : towers) {
            int x = t[0], y = t[1], q = t[2];
            int d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
            if (d2 <= r2) {
                double d = Math.sqrt(d2);
                int score = (int)Math.floor(q / (1.0 + d));
                if (score > bestScore) {
                    bestScore = score;
                    bestTower = new int[]{x, y};
                } else if (score == bestScore && bestTower.length > 0) {
                    if (x < bestTower[0] || (x == bestTower[0] && y < bestTower[1])) {
                        bestTower = new int[]{x, y};
                    }
                }
            }
        }
        return bestTower;
    }
}

